use vstd::prelude::*;

verus! {
    fn extract_rear_chars(l: &Vec<Vec<char>>) -> (r: Vec<char>)
        requires
            forall(|i: nat| i < l.len() ==> l[i].len() > 0), // Each inner vector is non-empty
        ensures
            r.len() == l.len(), // Output length equals the number of inner vectors
            forall(|i: nat| i < l.len() ==> r[i] == l[i][l[i].len() - 1]), // i-th output character is the last of the i-th inner vector
    {
        let mut r: Vec<char> = Vec::new();
        let mut idx: usize = 0;

        while idx < l.len()
            invariant
                idx <= l.len(), // idx is within bounds
                r.len() == idx, // r has the correct length so far
                forall(|i: nat| i < idx ==> r[i] == l[i][l[i].len() - 1]), // All previous characters are correctly extracted
            decreases l.len() - idx, // Decreases clause for termination
        {
            // Extract the last character of the current inner vector
            r.push(l[idx][l[idx].len() - 1]);
            idx = idx + 1; // Move to the next inner vector
        }

        r // Return the result
    }
}

